			        PostMessage(hWndDlg, WM_COMMAND, IDC_USEARCDIST, 0L);
					break; 
					
				case 2:
					SendDlgItemMessage (hWndDlg,IDC_USEARCDIST,BM_SETCHECK,FALSE,0L);
