					SendDlgItemMessage (hWndDlg,IDC_USETANDIST,BM_SETCHECK,TRUE,0L); 
			        PostMessage(hWndDlg, WM_COMMAND, IDC_USETANDIST, 0L);
					break;  
					
				case 3:
