            	 	 	HANDLE	hSymbol;
            	 	 	LPSYMBOL	CurSymbol;
            	 	 	
            	 	 	i=0;
            	 	 	while (SendDlgItemMessage(hWndDlg,PAR_VIS_LB,LB_GETTEXT,i++,(LPARAM)str) !=
            	 	 			LB_ERR)
            	 	 	{
            	 	 		lpTAB = _fstrrchr (str,'\t');
            	 	 		*lpTAB++ = 0;
            	 	 		MaxSym = max (MaxSym,atoi (lpTAB));
            	 	 	}
            	 	 	i=0;
            	 	 	while (SendDlgItemMessage(hWndDlg,SYM_VIS_LB,LB_GETTEXT,i++,(LPARAM)str) !=
            	 	 			LB_ERR)
            	 	 	{
            	 	 		lpTAB = _fstrrchr (str,'\t');
            	 	 		*lpTAB++ = 0;
            	 	 		MaxSym = max (MaxSym,atoi (lpTAB));
            	 	 	}
            	 	 	SetMaxSymNum (MaxSym);  
            	 	 	OpenSymDict (OF_READWRITE);
            	 	 	i=0;
            	 	 	while (SendDlgItemMessage(hWndDlg,PAR_VIS_LB,LB_GETTEXT,i++,(LPARAM)str) !=
            	 	 			LB_ERR)
            	 	 	{
            	 	 		lpTAB = _fstrrchr (str,'\t');
            	 	 		*lpTAB++ = 0;
            	 	 		SymNum = atoi (lpTAB);
            	 	 		lpTAB = _fstrrchr (str,'\t');
            	 	 		*lpTAB++ = 0;
            	 	 		ParNum = atoi (lpTAB); 
            	 	 		lpTAB = _fstrchr (str,'\t');
            	 	 		*lpTAB = 0;
							hSymbol = AllocateNewSymbol ();
							CurSymbol =(LPSYMBOL) GlobalLock (hSymbol);
					        CurSymbol->Type = 0;         
							_fstrcpy (CurSymbol->Name,str);  
							CurSymbol->Parent=ParNum;
							GlobalUnlock (hSymbol);		 
							SymNum = SaveSymbol(hSymbol,SymNum);   
							DestroySymbol (hSymbol); 
            	 	 	}
            	 	 	i=0;
            	 	 	while (SendDlgItemMessage(hWndDlg,SYM_VIS_LB,LB_GETTEXT,i++,(LPARAM)str) !=
            	 	 			LB_ERR)
            	 	 	{
            	 	 		lpTAB = _fstrrchr (str,'\t');
            	 	 		*lpTAB++ = 0;
            	 	 		SymNum = atoi (lpTAB);
            	 	 		lpTAB = _fstrrchr (str,'\t');
            	 	 		*lpTAB++ = 0;
            	 	 		ParNum = atoi (lpTAB); 
            	 	 		lpTAB = _fstrchr (str,'\t');
            	 	 		*lpTAB = 0;
							hSymbol = AllocateNewSymbol ();
							CurSymbol = (LPSYMBOL)GlobalLock (hSymbol);
					        CurSymbol->Type = 2;         
							_fstrcpy (CurSymbol->Name,str);  
							CurSymbol->Parent=ParNum;
							GlobalUnlock (hSymbol);		 
							SymNum = SaveSymbol(hSymbol,SymNum);   
							DestroySymbol (hSymbol); 
            	 	 	}
            	 	 	CloseSymDict();  
            	 	 	
