		 SendDlgItemMessage (hWndDlg,IDC_NEW_THEME,LB_ADDSTRING,0,(LPARAM)((LPSTR)"Hot Spot Theme\t14"));
		 SendDlgItemMessage (hWndDlg,IDC_NEW_THEME,LB_ADDSTRING,0,(LPARAM)((LPSTR)"Polygon Info Theme\t15"));
		 SendDlgItemMessage (hWndDlg,IDC_NEW_THEME,LB_ADDSTRING,0,(LPARAM)((LPSTR)"Graphics Function Theme\t16"));
		 SendDlgItemMessage (hWndDlg,IDC_NEW_THEME,LB_ADDSTRING,0,(LPARAM)((LPSTR)"Display Cache Theme\t17"));
		 SendDlgItemMessage (hWndDlg,IDC_NEW_THEME,LB_ADDSTRING,0,(LPARAM)((LPSTR)"Compare Viewports Theme\t18"));
		 SendDlgItemMessage (hWndDlg,IDC_NEW_THEME,LB_ADDSTRING,0,(LPARAM)((LPSTR)"Time Display Theme\t19"));
		 SendDlgItemMessage (hWndDlg,IDC_NEW_THEME,LB_ADDSTRING,0,(LPARAM)((LPSTR)"Point In Area Theme\t20"));
