		 SendDlgItemMessage(hWndDlg, IDC_NEW_THEME, LB_ADDSTRING, 0, (LPARAM)((LPSTR)"City Display Theme\t26"));
		 SendDlgItemMessage(hWndDlg, IDC_NEW_THEME, LB_ADDSTRING, 0, (LPARAM)((LPSTR)"Create Area in Mask Theme\t27"));
