         		_fstrcpy (CurView->lpFiles[LocAdded-1],VPAutoFile);   
         		_fstrncpy (CurView->FileID[LocAdded-1],LeafName,sizeof(CurView->FileID[LocAdded-1]));   
         		CurView->FileType[LocAdded-1] = GetFileTypeFromName(VPAutoFile,FALSE);
				switch (CurView->FileType[LocAdded-1])
				{
					default:
						break;
					case 1:
						CurView->FileType[LocAdded-1] = 2;
						break;
					case 2:
						CurView->FileType[LocAdded-1] = 4;
						if (*LastChr (Dir) == '\\')
							*LastChr (Dir) = 0;
						if ((pBS = strrchr (Dir,'\\')))
							strcpy (CurView->FileID[LocAdded-1],pBS+1);
						break;
					case 3:
						CurView->FileType[LocAdded-1] = 5; 
						break;
					case 4:
						CurView->FileType[LocAdded-1] = 3;
						break;
					case 8:
						CurView->FileType[LocAdded-1] = 9;
						break; 
				}
