                 DPOINT	LinkPoint, FirstIslandPoint, ControlPt;
                 HANDLE hPoly;
                 HPDPOINT pPoints;
                 HANDLE     hPoints, hnPoints, hLines;
                 short        NumPoints, Nump;  
                 short    NumSyms=0, n;  
                 HANDLE hSymDesc=0; 
