                 for (i=0;i<14;i++)
                	fputstring ("0.0",FidCvt);
                 GSSiClose (FidCvt);   
		         ConvertCoordClose (); 
                 _fstrcpy (SaveAlt,"[%ALT_PROJECTION]");
