void removeChrFromStr(LPSTR str, char *c)
{
	int i = 0;
	while (*str)
	{
		if (str == c)
		{
			i++;
			c = 0;
		}
		else
		{
			*str = *(str + i);
			str++;
		}
	}
	return;
}
void RemoveDuplicateChar(LPSTR str)
{
	int i = 0;
	char lastChr = 0;

	if (!str)
		return;
	lastChr = *str++;

	while (*str)
	{
		if (*(str+i) == lastChr)
		{
			i++;
			lastChr = 0;
		}
		else
		{
			*str = *(str + i);
			lastChr = *str;
			str++;
		}
	}
	return;
}
void ConvertFieldNameTo10Char(LPSTR nameIN)
{
	int ntoRemove;
		
	ntoRemove = strlen(nameIN) - 10;

	if (ntoRemove > 0)
		RemoveDuplicateChar(nameIN);
	ntoRemove = strlen(nameIN) - 10;

	while (ntoRemove > 0)
	{
		LPSTR pChr = strpbrk(nameIN, "aeiouy");
		if (pChr)
		{
			removeChrFromStr(nameIN, pChr);
			ntoRemove--;
		}
		else
			break;
	}
	while (ntoRemove > 0)
	{
		LPSTR pChr = strpbrk(nameIN, "AEIOUY");
		if (pChr)
		{
			removeChrFromStr(nameIN, pChr);
			ntoRemove--;
		}
		else
			break;
	}
	return;
}
